import { getStore } from "@netlify/blobs";
import { mkdir, writeFile } from "node:fs/promises";
import sharp from "sharp";

// =============================================================================
// Deals-Aholic Image Posts — Facebook automation for facebook.com/Dealsaholic2
// =============================================================================
// ISOLATION: this file, its env vars, and its Blobs store
// (facebook-image-posts-dealsaholic2) are used ONLY by this automation.
// It reads the shared "submissions" store READ-ONLY (get/list only — never
// set/setJSON/delete) and never writes back to it. Destination is identified
// exclusively by FB_PAGE_ID_DEALSAHOLIC2 (never by Page name).
//
// JoyLink: this reuses the SAME account-level JOYLINK_API_KEY /
// AMAZON_PARTNER_TAG env vars and the SAME "joylink-cache" Blobs store that
// post-to-facebook.mjs already uses. That cache is a generic, multi-consumer
// lookup (keyed by trackingId+asin/url) already shared across automations —
// it is not per-Page posting state, so reusing it does not touch any
// existing automation's dedup/lock/history. No new credential is required.
// =============================================================================


const PAGE_ID = process.env.FB_PAGE_ID_DEALSAHOLIC2;
const PAGE_TOKEN = process.env.FB_PAGE_TOKEN_DEALSAHOLIC2;
const POSTING_ENABLED = process.env.FB_POSTING_ENABLED_DEALSAHOLIC2 === "true";
const DRY_RUN = process.env.FB_DRY_RUN_DEALSAHOLIC2 !== "false"; // safe default: true
const POST_INTERVAL_MIN = parseInt(process.env.FB_POST_INTERVAL_DEALSAHOLIC2 || "60", 10) || 60;

const STORE_NAME = "facebook-image-posts-dealsaholic2";
const FB_GRAPH_VERSION = "v19.0";
const ALLOWED_IMAGE_HOSTS = new Set(["m.media-amazon.com", "images-na.ssl-images-amazon.com"]);
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
const LOCK_STALE_MS = 10 * 60 * 1000;
const SCAN_LIMIT = 400;
const MAX_ATTEMPTS = 3;
const TAG = "[dealsaholic2-fb]";

// ---- Embedded fonts (subsetted TTFs, base64) ----------------------------
// Netlify's Lambda runtime ships no system/emoji fonts, so text is rendered
// via fonts embedded directly in the SVG (@font-face + base64) rather than
// relying on the host. This was verified to render correctly with sharp.
const FONT_POPPINS_XB = "";
const FONT_POPPINS_B = "";
const FONT_POPPINS_SB = "";
const FONT_PLAYFAIR_BI = "";
const FONT_PLAYFAIR_XB = "";

let embeddedFontsReady;

async function ensureEmbeddedFonts() {
  if (!embeddedFontsReady) {
    embeddedFontsReady = (async () => {
      // librsvg (used by sharp on Netlify) does not load data-URL @font-face
      // declarations reliably. Install the embedded fonts into the function's
      // writable /tmp directory and point fontconfig at that directory before
      // the first SVG is rendered.
      const fontDir = "/tmp/dealsaholic2-fonts";
      const cacheDir = "/tmp/dealsaholic2-font-cache";
      const configPath = `${fontDir}/fonts.conf`;
      await mkdir(fontDir, { recursive: true });
      await mkdir(cacheDir, { recursive: true });
      await Promise.all([
        writeFile(`${fontDir}/Poppins-ExtraBold.ttf`, Buffer.from(FONT_POPPINS_XB, "base64")),
        writeFile(`${fontDir}/Poppins-Bold.ttf`, Buffer.from(FONT_POPPINS_B, "base64")),
        writeFile(`${fontDir}/Poppins-SemiBold.ttf`, Buffer.from(FONT_POPPINS_SB, "base64")),
        writeFile(`${fontDir}/PlayfairDisplay-BoldItalic.ttf`, Buffer.from(FONT_PLAYFAIR_BI, "base64")),
        writeFile(`${fontDir}/PlayfairDisplay-ExtraBold.ttf`, Buffer.from(FONT_PLAYFAIR_XB, "base64")),
      ]);
      await writeFile(
        configPath,
        `<?xml version="1.0"?>
<!DOCTYPE fontconfig SYSTEM "fonts.dtd">
<fontconfig>
  <dir>${fontDir}</dir>
  <cachedir>${cacheDir}</cachedir>
</fontconfig>`,
      );
      process.env.FONTCONFIG_FILE = configPath;
      process.env.FONTCONFIG_PATH = fontDir;
    })();
  }
  return embeddedFontsReady;
}

// ---- small utilities -------------------------------------------------------
function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function wrapText(title, maxCharsPerLine, maxLines) {
  const words = String(title || "").trim().split(/\s+/);
  const lines = [];
  let current = "";
  for (const w of words) {
    const candidate = current ? current + " " + w : w;
    if (candidate.length > maxCharsPerLine && current) {
      lines.push(current);
      current = w;
      if (lines.length === maxLines - 1) break;
    } else {
      current = candidate;
    }
  }
  if (current) lines.push(current);
  const consumed = lines.join(" ").split(/\s+/).length;
  if (consumed < words.length) {
    let last = lines[lines.length - 1];
    while (last.length > maxCharsPerLine - 1) last = last.slice(0, -1);
    lines[lines.length - 1] = last.replace(/[.,;:\s]+$/, "") + "…";
  }
  return lines.slice(0, maxLines);
}

function fitFontSize(text, maxWidth, baseFontSize, avgCharWidth = 0.62, minFontSize = 48) {
  const estWidth = String(text).length * baseFontSize * avgCharWidth;
  if (estWidth <= maxWidth) return baseFontSize;
  return Math.max(minFontSize, Math.floor(baseFontSize * (maxWidth / estWidth)));
}

function flameIcon(x, y, scale) {
  return `
  <g transform="translate(${x},${y}) scale(${scale})">
    <path d="M22 0 C10 14 2 26 2 37 C2 51 12 61 24 61 C37 61 47 51 47 38 C47 30 42 25 39 20
             C39 29 34 34 29 34 C24 34 21 30 22 24 C23 16 18 9 22 0 Z" fill="#d81336"/>
    <path d="M24 20 C18 29 15 36 15 43 C15 50 19 55 25 55 C31 55 35 50 35 44
             C35 40 32 37 30 34 C30 39 27 42 24 42 C21 42 19 40 20 36 C21 30 18 25 24 20 Z" fill="#ffb648"/>
  </g>`;
}

function sparkle(x, y, s, color) {
  return `<path transform="translate(${x},${y}) scale(${s})" d="M0 -10 L2.3 -2.3 L10 0 L2.3 2.3 L0 10 L-2.3 2.3 L-10 0 L-2.3 -2.3 Z" fill="${color}"/>`;
}

function starburst(cx, cy, rOuter, rInner, points) {
  let d = "";
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? rOuter : rInner;
    const a = (Math.PI / points) * i - Math.PI / 2;
    const x = cx + r * Math.cos(a);
    const y = cy + r * Math.sin(a);
    d += (i === 0 ? "M" : "L") + x.toFixed(1) + " " + y.toFixed(1) + " ";
  }
  return d + "Z";
}

function parsePriceNumber(v) {
  if (typeof v === "number" && isFinite(v)) return v;
  if (typeof v !== "string") return null;
  const m = v.replace(/,/g, "").match(/([0-9]+(\.[0-9]{1,2})?)/);
  return m ? parseFloat(m[1]) : null;
}

function formatUsd(n) {
  return `$${n.toFixed(2)}`;
}

// Deal records come from two different submission pipelines with different
// field names (title/url/imageUrl/discount for admin-created deals vs.
// productTitle/productUrl/image/discountPercent for email-submitted deals).
// Resolve both shapes defensively so this automation works for either.
function resolveDealFields(deal) {
  return {
    title: deal.title || deal.productTitle || "",
    url: deal.url || deal.productUrl || "",
    imageUrl: deal.imageUrl || deal.image || null,
    asin: deal.asin || null,
    discountRaw: deal.discount ?? deal.discountPercent ?? null,
    price: deal.price,
    originalPrice: deal.originalPrice,
    promoCode:
      deal.discountCode ||
      deal.promoCode ||
      deal.couponCode ||
      deal.coupon_code ||
      deal.promo_code ||
      null,
  };
}

function normalizePromoCode(value) {
  const code = String(value || "").trim();
  if (!code || /^(none|null|n\/a|no code)$/i.test(code)) return null;
  return code.slice(0, 32);
}

function computePricing(fields) {
  const price = parsePriceNumber(fields.price);
  if (price === null) return null; // unverified price -> caller must skip
  const originalPrice = parsePriceNumber(fields.originalPrice);
  let discountPct = null;
  let savings = null;
  if (originalPrice !== null && originalPrice > price) {
    savings = Math.round((originalPrice - price) * 100) / 100;
    discountPct = Math.round(((originalPrice - price) / originalPrice) * 100);
  } else if (typeof fields.discountRaw === "number" && fields.discountRaw > 0) {
    discountPct = Math.round(fields.discountRaw);
  }
  return {
    price,
    originalPrice,
    priceDisplay: formatUsd(price),
    originalPriceDisplay: originalPrice !== null ? formatUsd(originalPrice) : null,
    discountPct,
    savingsDisplay: savings !== null ? formatUsd(savings) : null,
  };
}

function normalizeDedupKey(fields) {
  if (fields.asin) return `asin:${String(fields.asin).trim().toUpperCase()}`;
  try {
    const u = new URL(fields.url);
    u.search = "";
    u.hash = "";
    const s = u.toString().toLowerCase().replace(/\/$/, "");
    return `url:${s}`;
  } catch {
    return `title:${String(fields.title || "").trim().toLowerCase()}`;
  }
}

function shortenTitle(title, maxLen = 90) {
  const t = String(title || "").trim();
  if (t.length <= maxLen) return t;
  return t.slice(0, maxLen - 1).replace(/\s+\S*$/, "") + "…";
}

async function downloadAuthorizedImage(imageUrl) {
  let u;
  try {
    u = new URL(imageUrl);
  } catch {
    return { error: "invalid image url" };
  }
  if (u.protocol !== "https:" || !ALLOWED_IMAGE_HOSTS.has(u.hostname)) {
    return { error: `image host not authorized: ${u.hostname}` };
  }
  let res;
  try {
    res = await fetch(u, {
      signal: AbortSignal.timeout(10000),
      headers: { "User-Agent": "Mozilla/5.0 (compatible; DealsAholic2ImageBot/1.0)" },
    });
  } catch (e) {
    return { error: `image fetch failed: ${e.message}` };
  }
  if (!res.ok) return { error: `image fetch status ${res.status}` };
  const ct = res.headers.get("content-type") || "";
  if (!ct.startsWith("image/")) return { error: `unexpected content-type ${ct}` };
  const buf = Buffer.from(await res.arrayBuffer());
  if (buf.length > MAX_IMAGE_BYTES) return { error: "image too large" };
  return { buf };
}

// Same conversion as post-to-facebook.mjs: uses the site's existing JoyLink
// account (JOYLINK_API_KEY, AMAZON_PARTNER_TAG) and its shared cache, purely
// for read (cache hit) or additive cache-write (new lookup) — never touches
// any Page-specific state. Non-Amazon links and missing config are no-ops.
async function getJoyLinkUrl(amazonUrl, asin) {
  const apiKey = process.env.JOYLINK_API_KEY;
  if (!apiKey || !amazonUrl) return null;

  const cache = getStore("joylink-cache");
  const trackingId = process.env.AMAZON_PARTNER_TAG || "daholic-20";
  const cacheKey = `${trackingId}:${asin || amazonUrl}`;
  try {
    const cached = await cache.get(cacheKey, { type: "json" });
    if (cached?.url) return cached.url;
  } catch {}

  try {
    const res = await fetch("https://api.joylink.io/public/createlink", {
      method: "POST",
      signal: AbortSignal.timeout(10000),
      headers: { "Content-Type": "application/json", "X-API-Key": apiKey },
      body: JSON.stringify({ destination: amazonUrl, trackingid: trackingId }),
    });
    const data = await res.json();
    if (res.ok && data.url) {
      await cache.setJSON(cacheKey, { url: data.url, createdAt: new Date().toISOString() }).catch(() => {});
      return data.url;
    }
    console.error(TAG, "JoyLink API error:", JSON.stringify(data));
  } catch (err) {
    console.error(TAG, "JoyLink request failed:", err.message);
  }
  return null;
}


// ---- image compositor -------------------------------------------------------
// Deterministic compositing only (sharp/SVG). Never redraws, alters, or
// regenerates the product photo itself — only places the exact downloaded
// image into the template alongside verified text.
async function composeDealImage({ productBuf, title, pricing, benefits, promoCode }) {
  await ensureEmbeddedFonts();

  const W = 1080, H = 1350;
  const hasBenefits = Array.isArray(benefits) && benefits.length > 0;

  const frame = 30;
  const cardX = frame, cardY = frame, cardW = W - frame * 2, cardH = H - frame * 2;
  const pad = 34;
  const contentX = cardX + pad;
  const contentW = cardW - pad * 2;

  const titleLines = wrapText(title, 26, 2);
  const headerH = 132;
  const ribbonH = titleLines.length > 1 ? 138 : 90;
  const headerTop = cardY;
  const ribbonTop = headerTop + headerH;
  const mainTop = ribbonTop + ribbonH + 26;
  const mainBottom = cardY + cardH - 30;
  const mainH = mainBottom - mainTop;
  const gap = 22;

  const leftW = Math.round(contentW * 0.585);
  const rightW = contentW - leftW - 28;
  const leftX = contentX;
  const rightX = contentX + leftW + 28;

  const benefitsH = hasBenefits ? 156 : 0;
  const bannerH = pricing.discountPct ? 116 : 0;
  const gapsInLeft = (hasBenefits ? 1 : 0) + (pricing.discountPct ? 1 : 0);
  const heroH = mainH - benefitsH - bannerH - gap * gapsInLeft;

  const fitted = await sharp(productBuf)
    .resize(leftW - 24, heroH - 24, { fit: "contain", background: { r: 255, g: 255, b: 255, alpha: 1 } })
    .jpeg({ quality: 92 })
    .toBuffer();
  const productB64 = fitted.toString("base64");

  const benefitsY = mainTop + heroH + gap;
  const benefitCards = hasBenefits
    ? benefits
        .slice(0, 3)
        .map((b, i) => {
          const n = Math.min(benefits.length, 3);
          const g = 16;
          const cw = (leftW - g * (n - 1)) / n;
          const x = leftX + i * (cw + g);
          const y = benefitsY;
          const ch = benefitsH;
          const lines = wrapText(b, 13, 2);
          return `
      <rect x="${x}" y="${y}" width="${cw}" height="${ch}" rx="16" fill="#fdf1ec" stroke="#f0d3c7" stroke-width="1.5"/>
      <circle cx="${x + 32}" cy="${y + 34}" r="20" fill="#d81336"/>
      <text x="${x + 32}" y="${y + 42}" font-family="Poppins" font-weight="800" font-size="21" fill="#ffffff" text-anchor="middle">${i + 1}</text>
      ${lines.map((line, li) => `<text x="${x + cw / 2}" y="${y + 88 + li * 27}" font-family="Poppins" font-weight="800" font-size="19" fill="#242424" text-anchor="middle" letter-spacing="0.2">${esc(line.toUpperCase())}</text>`).join("")}
    `;
        })
        .join("")
    : "";

  const bannerY = benefitsY + benefitsH + (hasBenefits ? gap : 0);
  const banner = pricing.discountPct
    ? `
    <rect x="${leftX}" y="${bannerY}" width="${leftW}" height="${bannerH}" rx="16" fill="url(#redGrad)"/>
    <text x="${leftX + leftW / 2}" y="${bannerY + bannerH / 2 + 20}" font-family="Poppins" font-weight="800" font-size="56" fill="#ffffff" text-anchor="middle" letter-spacing="1">${pricing.discountPct}% OFF</text>
  `
    : "";

  const sidebarX = rightX, sidebarY = mainTop, sidebarW = rightW, sidebarH = mainH;
  const priceCX = sidebarX + sidebarW / 2;
  const priceTop = sidebarY + sidebarH * 0.2;
  const watermarkH = 88;
  const watermarkY = sidebarY + sidebarH - watermarkH;

  const priceFontSize = fitFontSize(pricing.priceDisplay, sidebarW - 44, 118);
  const priceLineY = priceTop + 95 + priceFontSize * 0.62;
  const code = normalizePromoCode(promoCode);
  const codeBoxY = Math.min(watermarkY - 126, priceLineY + (pricing.savingsDisplay ? 150 : pricing.originalPriceDisplay ? 92 : 68));
  const codeFontSize = code ? fitFontSize(code, sidebarW - 66, 39) : 0;

  const starCx = leftX + 66, starCy = mainTop + 66;
  const starburstBadge = pricing.discountPct
    ? `
    <g filter="url(#softShadow)">
      <path d="${starburst(starCx, starCy, 62, 46, 10)}" fill="url(#redGrad)"/>
    </g>
    <text x="${starCx}" y="${starCy - 6}" font-family="Poppins" font-weight="800" font-size="30" fill="#ffffff" text-anchor="middle">-${pricing.discountPct}%</text>
    <text x="${starCx}" y="${starCy + 20}" font-family="Poppins" font-weight="700" font-size="15" fill="#ffffff" text-anchor="middle" letter-spacing="1">OFF</text>
  `
    : "";

  const svg = `<svg width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg">
<defs>
  <linearGradient id="frameGrad" x1="0%" y1="0%" x2="100%" y2="100%">
    <stop offset="0%" stop-color="#f3c9c2"/><stop offset="30%" stop-color="#f7e2c8"/>
    <stop offset="55%" stop-color="#f6cfd6"/><stop offset="80%" stop-color="#eec3d9"/>
    <stop offset="100%" stop-color="#f3c9c2"/>
  </linearGradient>
  <linearGradient id="sidebarGrad" x1="0%" y1="0%" x2="0%" y2="100%">
    <stop offset="0%" stop-color="#fff7f3"/><stop offset="100%" stop-color="#fbe4d9"/>
  </linearGradient>
  <linearGradient id="redGrad" x1="0%" y1="0%" x2="100%" y2="100%">
    <stop offset="0%" stop-color="#e21c40"/><stop offset="100%" stop-color="#b80f2c"/>
  </linearGradient>
  <filter id="softShadow" x="-30%" y="-30%" width="160%" height="160%">
    <feDropShadow dx="0" dy="6" stdDeviation="10" flood-color="#000000" flood-opacity="0.15"/>
  </filter>
  <filter id="priceGlow" x="-50%" y="-50%" width="200%" height="200%">
    <feDropShadow dx="0" dy="0" stdDeviation="14" flood-color="#e21c40" flood-opacity="0.28"/>
  </filter>
</defs>
<rect width="${W}" height="${H}" fill="url(#frameGrad)"/>
<rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="18" fill="#ffffff"/>
${flameIcon(cardX + 54, headerTop + 36, 1.05)}
<text x="${cardX + cardW / 2}" y="${headerTop + 86}" font-family="Playfair Display" font-weight="800" font-size="64" fill="#141414" text-anchor="middle" letter-spacing="1">DEAL OF THE DAY</text>
${flameIcon(cardX + cardW - 106, headerTop + 36, 1.05)}
<rect x="${cardX}" y="${ribbonTop}" width="${cardW}" height="${ribbonH}" fill="url(#redGrad)"/>
${titleLines
  .map((line, i) => {
    const ty = titleLines.length > 1 ? ribbonTop + ribbonH / 2 - 18 + i * 50 : ribbonTop + ribbonH / 2 + 16;
    return `<text x="${cardX + cardW / 2}" y="${ty}" font-family="Poppins" font-weight="800" font-size="42" fill="#ffffff" text-anchor="middle" letter-spacing="0.5">${esc(line.toUpperCase())}</text>`;
  })
  .join("")}
<g filter="url(#softShadow)">
  <rect x="${leftX}" y="${mainTop}" width="${leftW}" height="${heroH}" rx="20" fill="#ffffff" stroke="#f0d3c7" stroke-width="1.5"/>
</g>
<image x="${leftX + 12}" y="${mainTop + 12}" width="${leftW - 24}" height="${heroH - 24}" href="data:image/jpeg;base64,${productB64}" preserveAspectRatio="xMidYMid meet"/>
${starburstBadge}
${benefitCards}
${banner}
<g filter="url(#softShadow)">
  <rect x="${sidebarX}" y="${sidebarY}" width="${sidebarW}" height="${sidebarH}" rx="20" fill="url(#sidebarGrad)"/>
</g>
${sparkle(sidebarX + 34, sidebarY + 40, 1.2, "#f0c2b3")}
${sparkle(sidebarX + sidebarW - 30, sidebarY + sidebarH * 0.5, 1, "#f0c2b3")}
<text x="${priceCX}" y="${priceTop}" font-family="Playfair Display" font-weight="800" font-size="38" fill="#3a2a26" text-anchor="middle" letter-spacing="1">NOW</text>
<text x="${priceCX}" y="${priceTop + 50}" font-family="Playfair Display" font-weight="800" font-size="38" fill="#3a2a26" text-anchor="middle" letter-spacing="1">ONLY</text>
<g filter="url(#priceGlow)">
  <text x="${priceCX}" y="${priceLineY}" font-family="Poppins" font-weight="800" font-size="${priceFontSize}" fill="#d81336" text-anchor="middle">${esc(pricing.priceDisplay)}</text>
</g>
${pricing.originalPriceDisplay ? `<text x="${priceCX}" y="${priceLineY + 48}" font-family="Poppins" font-weight="600" font-size="34" fill="#a89089" text-anchor="middle" text-decoration="line-through">${esc(pricing.originalPriceDisplay)}</text>` : ""}
${pricing.savingsDisplay
  ? `
  <rect x="${priceCX - Math.min(sidebarW - 32, 236) / 2}" y="${priceLineY + 74}" width="${Math.min(sidebarW - 32, 236)}" height="52" rx="26" fill="#ffffff" stroke="#d81336" stroke-width="2.5"/>
  <text x="${priceCX}" y="${priceLineY + 108}" font-family="Poppins" font-weight="700" font-size="23" fill="#d81336" text-anchor="middle">SAVE ${esc(pricing.savingsDisplay)}</text>
`
  : ""}
${code
  ? `
  <text x="${priceCX}" y="${codeBoxY - 12}" font-family="Poppins" font-weight="700" font-size="22" fill="#3a2a26" text-anchor="middle" letter-spacing="1">USE PROMO CODE</text>
  <rect x="${sidebarX + 18}" y="${codeBoxY}" width="${sidebarW - 36}" height="72" rx="14" fill="#ffffff" stroke="#d81336" stroke-width="3" stroke-dasharray="9 6"/>
  <text x="${priceCX}" y="${codeBoxY + 49}" font-family="Poppins" font-weight="800" font-size="${codeFontSize}" fill="#d81336" text-anchor="middle" letter-spacing="1">${esc(code.toUpperCase())}</text>
`
  : ""}
<path d="M ${sidebarX + sidebarW - 10} ${watermarkY + watermarkH - 20}
  C ${sidebarX + sidebarW - 40} ${watermarkY + 4}, ${sidebarX + 40} ${watermarkY}, ${sidebarX + 12} ${watermarkY + watermarkH - 26}
  C ${sidebarX + 40} ${watermarkY + watermarkH + 8}, ${sidebarX + sidebarW - 36} ${watermarkY + watermarkH + 12}, ${sidebarX + sidebarW - 10} ${watermarkY + watermarkH - 20} Z"
  fill="#f6ddd2"/>
<text x="${sidebarX + sidebarW / 2}" y="${watermarkY + watermarkH / 2 + 11}" font-family="Playfair Display" font-weight="700" font-style="italic" font-size="30" fill="#3a2a26" text-anchor="middle">@Deals_aholic</text>
</svg>`;

  return sharp(Buffer.from(svg)).png().toBuffer();
}

// ---- caption ----------------------------------------------------------------
const HASHTAG_ROTATIONS = [
  ["#AmazonDeals", "#DealAlert", "#Savings", "#ShopNow"],
  ["#Deals", "#Sale", "#Discount", "#OnlineShopping"],
  ["#DailyDeals", "#PriceDrop", "#Bargain", "#MustHave"],
  ["#AmazonFinds", "#HotDeal", "#SaveMoney", "#ShoppingDeals"],
];

function categoryHashtag(title) {
  const value = String(title || "").toLowerCase();
  if (/shoe|heel|sandal|dress|shirt|pants|fashion|women|men/.test(value)) return "#FashionDeals";
  if (/beauty|makeup|skin|hair|cosmetic/.test(value)) return "#BeautyDeals";
  if (/kitchen|cook|air fryer|coffee|blender/.test(value)) return "#KitchenDeals";
  if (/home|furniture|mattress|bed|decor|light|vacuum/.test(value)) return "#HomeDeals";
  if (/camp|outdoor|garden|patio|travel/.test(value)) return "#OutdoorDeals";
  if (/phone|tablet|computer|headphone|speaker|electronic/.test(value)) return "#TechDeals";
  return "#GreatDeals";
}

function buildHashtags(title) {
  const rotation = HASHTAG_ROTATIONS[Math.floor(Date.now() / 3600000) % HASHTAG_ROTATIONS.length];
  return ["#ad", "#DealsAholic", categoryHashtag(title), ...rotation].join(" ");
}

function buildCaption(fields, pricing, benefits, postUrl) {
  const title = shortenTitle(fields.title);
  let priceLine = pricing.priceDisplay;
  if (pricing.discountPct) priceLine += ` (${pricing.discountPct}% off)`;
  else if (pricing.originalPriceDisplay) priceLine += ` (was ${pricing.originalPriceDisplay})`;

  const benefitSentence =
    benefits.length > 0
      ? `Now with ${benefits[0].toLowerCase()}.`
      : pricing.savingsDisplay
        ? `Save ${pricing.savingsDisplay} today.`
        : "Grab it while it's live.";

  const promoCode = normalizePromoCode(fields.promoCode);

  return [
    `🔥 ${title} — ${priceLine}`,
    ...(promoCode ? [`🏷️ USE PROMO CODE: ${promoCode.toUpperCase()}`] : []),
    benefitSentence,
    postUrl || fields.url,
    "For more deals, check out our website: https://deals-aholic.com/",
    "Prices and availability may change.",
    "As an Amazon Associate we earn from qualifying purchases.",
    buildHashtags(fields.title),
  ].join("\n\n");
}

// ---- Facebook Graph API ------------------------------------------------------
async function isAlreadyPostedLive(title, url) {
  try {
    const res = await fetch(
      `https://graph.facebook.com/${FB_GRAPH_VERSION}/${PAGE_ID}/posts?fields=message&limit=50&access_token=${PAGE_TOKEN}`,
      { signal: AbortSignal.timeout(10000) }
    );
    if (!res.ok) return false;
    const data = await res.json();
    const posts = data.data || [];
    return posts.some((p) => p.message && ((url && p.message.includes(url)) || (title && p.message.includes(title))));
  } catch {
    return false;
  }
}

async function publishPhoto(imageBuffer, caption) {
  const form = new FormData();
  form.append("source", new Blob([imageBuffer], { type: "image/png" }), "deal.png");
  form.append("caption", caption);
  form.append("access_token", PAGE_TOKEN);
  form.append("published", "true");
  const res = await fetch(`https://graph.facebook.com/${FB_GRAPH_VERSION}/${PAGE_ID}/photos`, {
    method: "POST",
    body: form,
    signal: AbortSignal.timeout(20000),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.error) {
    throw new Error(`Facebook publish failed: ${data.error?.message || res.status}`);
  }
  return data;
}

// ---- lock ---------------------------------------------------------------------
async function acquireLock(store) {
  const existing = await store.get("lock", { type: "json" }).catch(() => null);
  if (existing && Date.now() - new Date(existing.startedAt).getTime() < LOCK_STALE_MS) {
    return false;
  }
  await store.setJSON("lock", { startedAt: new Date().toISOString() });
  return true;
}

async function releaseLock(store) {
  await store.delete("lock").catch(() => {});
}

function jsonResponse(obj) {
  return new Response(JSON.stringify(obj, null, 2), { headers: { "Content-Type": "application/json" } });
}

// ---- main handler ---------------------------------------------------------
export default async function handler() {
  const log = (...args) => console.log(TAG, ...args);

  if (!PAGE_ID || !PAGE_TOKEN) {
    log("Missing FB_PAGE_ID_DEALSAHOLIC2 or FB_PAGE_TOKEN_DEALSAHOLIC2 — aborting.");
    return jsonResponse({ ok: false, reason: "missing_credentials" });
  }

  if (!POSTING_ENABLED) {
    log("Disabled via FB_POSTING_ENABLED_DEALSAHOLIC2 (kill switch) — no-op.");
    return jsonResponse({ ok: false, reason: "disabled" });
  }

  const store = getStore(STORE_NAME);

  if (!DRY_RUN) {
    const lastPost = await store.get("last-post", { type: "json" }).catch(() => null);
    if (lastPost) {
      const elapsedMin = (Date.now() - new Date(lastPost.postedAt).getTime()) / 60000;
      if (elapsedMin < POST_INTERVAL_MIN) {
        log(`Throttled — last post ${elapsedMin.toFixed(1)}min ago, interval is ${POST_INTERVAL_MIN}min.`);
        return jsonResponse({ ok: true, reason: "throttled" });
      }
    }
  }

  const locked = await acquireLock(store);
  if (!locked) {
    log("Another run holds the lock — skipping.");
    return jsonResponse({ ok: true, reason: "locked" });
  }

  try {
    // READ-ONLY access to the shared submissions store: only .get()/.list()
    // are ever called on it below. Nothing is ever written back to it.
    const submissions = getStore("submissions");
    let keys = await submissions.get("index", { type: "json" }).catch(() => null);
    if (!Array.isArray(keys) || keys.length === 0) {
      const { blobs } = await submissions.list();
      keys = blobs.map((b) => b.key);
    }
    if (keys.length === 0) {
      log("No submissions found.");
      return jsonResponse({ ok: true, reason: "no_deals" });
    }

    const cursorRec = await store.get("cursor", { type: "json" }).catch(() => null);
    const position = cursorRec?.position || 0;

    let scanned = 0;
    let result = null;
    const limit = Math.min(SCAN_LIMIT, keys.length);

    while (scanned < limit) {
      const idx = (position + scanned) % keys.length;
      scanned++;
      const key = keys[idx];
      if (key === "index") continue;

      const deal = await submissions.get(key, { type: "json" }).catch(() => null);
      if (!deal || deal.status !== "approved") continue;

      const fields = resolveDealFields(deal);
      const dedupKey = normalizeDedupKey(fields);

      const [posted, skipped, failRec] = await Promise.all([
        store.get(`posted:${dedupKey}`, { type: "json" }).catch(() => null),
        store.get(`skip:${dedupKey}`, { type: "json" }).catch(() => null),
        store.get(`fail:${dedupKey}`, { type: "json" }).catch(() => null),
      ]);
      if (posted || skipped) continue;
      if (failRec && failRec.count >= MAX_ATTEMPTS) {
        await store.setJSON(`skip:${dedupKey}`, { reason: "max retries exceeded", skippedAt: new Date().toISOString() });
        continue;
      }

      // ---- validation (never publish unverified data) ----
      const pricing = computePricing(fields);
      if (!pricing) {
        await store.setJSON(`skip:${dedupKey}`, { reason: "missing or unverified price", skippedAt: new Date().toISOString() });
        continue;
      }
      if (!fields.imageUrl) {
        await store.setJSON(`skip:${dedupKey}`, { reason: "missing image", skippedAt: new Date().toISOString() });
        continue;
      }
      if (!fields.url) {
        await store.setJSON(`skip:${dedupKey}`, { reason: "missing affiliate link", skippedAt: new Date().toISOString() });
        continue;
      }
      if (!fields.title) {
        await store.setJSON(`skip:${dedupKey}`, { reason: "missing title", skippedAt: new Date().toISOString() });
        continue;
      }

      // ---- secondary live safety net (skip in dry run) ----
      if (!DRY_RUN) {
        const already = await isAlreadyPostedLive(fields.title, fields.url);
        if (already) {
          await store.setJSON(`posted:${dedupKey}`, {
            postedAt: new Date().toISOString(),
            note: "detected already live on the Page; not tracked previously",
          });
          continue;
        }
      }

      const imgResult = await downloadAuthorizedImage(fields.imageUrl);
      if (imgResult.error) {
        const count = (failRec?.count || 0) + 1;
        await store.setJSON(`fail:${dedupKey}`, { count, lastError: imgResult.error, lastAttempt: new Date().toISOString() });
        continue;
      }

      const benefits = Array.isArray(deal.benefits)
        ? deal.benefits.filter(Boolean).slice(0, 3)
        : Array.isArray(deal.features)
          ? deal.features.filter(Boolean).slice(0, 3)
          : [];

      // JoyLink conversion (Amazon links only) — matches post-to-facebook.mjs.
      // Dedup and the live-post check above already used the ORIGINAL url,
      // so this only affects what link gets published in the caption.
      const isAmazon = /amazon\./i.test(fields.url || "");
      const joylinkUrl = isAmazon ? await getJoyLinkUrl(fields.url, fields.asin) : null;
      const postUrl = joylinkUrl || fields.url;

      let imageBuffer;
      try {
        imageBuffer = await composeDealImage({
          productBuf: imgResult.buf,
          title: fields.title,
          pricing,
          benefits,
          promoCode: fields.promoCode,
        });
      } catch (e) {
        const count = (failRec?.count || 0) + 1;
        await store.setJSON(`fail:${dedupKey}`, { count, lastError: `compose failed: ${e.message}`, lastAttempt: new Date().toISOString() });
        continue;
      }

      const caption = buildCaption(fields, pricing, benefits, postUrl);

      if (DRY_RUN) {
        log(`[DRY RUN] Would post ${dedupKey}: ${fields.title}`);
        await store.setJSON("cursor", { position: (idx + 1) % keys.length });
        result = {
          ok: true,
          dryRun: true,
          dealTitle: fields.title,
          dedupKey,
          caption,
          image: `data:image/png;base64,${imageBuffer.toString("base64")}`,
        };
        break;
      }

      try {
        const fbResult = await publishPhoto(imageBuffer, caption);
        await store.setJSON(`posted:${dedupKey}`, {
          postedAt: new Date().toISOString(),
          facebookPostId: fbResult.post_id || fbResult.id,
          title: fields.title,
        });
        await store.setJSON("last-post", { postedAt: new Date().toISOString() });
        await store.setJSON("cursor", { position: (idx + 1) % keys.length });
        log(`Posted ${dedupKey} -> ${fbResult.post_id || fbResult.id}`);
        result = { ok: true, dealTitle: fields.title, dedupKey, facebookPostId: fbResult.post_id || fbResult.id };
      } catch (e) {
        const count = (failRec?.count || 0) + 1;
        await store.setJSON(`fail:${dedupKey}`, { count, lastError: e.message, lastAttempt: new Date().toISOString() });
        log(`Publish failed for ${dedupKey}: ${e.message}`);
        result = { ok: false, reason: "publish_failed", dedupKey, error: e.message };
      }
      break; // one deal per invocation, success or failure
    }

    if (!result) {
      result = { ok: true, reason: "no_eligible_deal_found", scanned };
    }
    return jsonResponse(result);
  } finally {
    await releaseLock(store);
  }
}

export const config = {
  schedule: "*/5 * * * *",
};
